"""Step A: exact realistic scope for levels 1-10 + Daily Boss, from origin/integration/v2 layout data.
LevelBuilder (integration/v2) spawns every layout block as a scaled cube by `mat`; no level references a Bld_* hero building
(chapter1.json has no heroSlot; OfflineMeta preview slots have fbx=""), so the scope is the material block pieces + 2 dressed props.
usage: python3 scope.py [ref]  -> models/Realistic_Scope_L1-10.md + models/Realistic_Scope_L1-10.json"""
import json,subprocess,sys,os,collections
REF=sys.argv[1] if len(sys.argv)>1 else "origin/integration/v2"; ROOT=os.path.abspath(os.path.join(os.path.dirname(__file__),"..","..",".."))
D="Assets/_Project/Resources/Data/"
def show(p): return json.loads(subprocess.check_output(["git","-C",ROOT,"show",f"{REF}:{D}{p}"]))
ch=show("chapter1.json"); meta=show("meta_v2.json")
LV=[(f"L{l['number']}",l["layout"],l["name"]) for l in ch["levels"] if 1<=l["number"]<=10]
LV+=[(f"DB{i+1}",lay,meta["dailyBoss"]["names"][i] if i<len(meta["dailyBoss"]["names"]) else lay) for i,lay in enumerate(meta["dailyBoss"]["layouts"])]
KIT={"wood":"Wood","brick":"Brick","steel":"Steel"}
def classify(b):
    m=KIT[b["mat"]]; s=b["s"]; a,bb,c=sorted(s); thin=s.index(a)
    if b["role"]=="island": return ("HELD","Island rock / plinth (island held)","Kit_Base_Indestructible")
    if b["id"]=="barrelDecor": return ("Kit_RealProps_Barrel","barrel decor","Kit_Props_Barrel (+ realism Prop_Barrel)")
    if b.get("explosive") or b["id"]=="crate": return ("Kit_RealProps_Crate","explosive crate","Kit_Props_Crate (+ realism Prop_Crate)")
    if b["role"]=="roof": return ("Kit_RealRoof_Roof","roof slab","Kit_Roof_Roof")
    if bb<=0.65 and c>=1.8*bb: return (f"Kit_Real{m}_Joint","post / beam / pillar",f"Kit_{m}_Joint")
    if a<=0.5 and a<=0.4*bb: return ((f"Kit_Real{m}_Floor","slab / deck",f"Kit_{m}_Floor") if thin==1 else (f"Kit_Real{m}_Wall","wall panel",f"Kit_{m}_Wall"))
    return (f"Kit_Real{m}_Block","solid block (box)",f"new Block module, kit v3.1 fracture setup (build_kit2.py)")
rows=[]; use=collections.OrderedDict()
for tag,lay,name in LV:
    for b in show(f"Layouts/{lay}.json")["blocks"]:
        mod,kind,src=classify(b); rows.append((tag,lay,b,mod,kind,src))
        u=use.setdefault(mod,{"kind":kind,"src":src,"count":0,"levels":collections.Counter(),"blocks":[],"indestructible":0})
        u["count"]+=1; u["levels"][tag]+=1; u["blocks"].append(f"{tag}:{b['id']}"); u["indestructible"]+=bool(b["indestructible"])
order=sorted([k for k in use if k!="HELD"],key=lambda k:(-use[k]["count"],-len(use[k]["levels"]),k))
out=os.path.join(ROOT,"models","Realistic_Scope_L1-10.md"); os.makedirs(os.path.dirname(out),exist_ok=True)
L=["# Realistic scope: levels 1-10 + Daily Boss","",f"Generated by `Tools/Blender/realistic/scope.py` from `{REF}` (`{D}chapter1.json`, `meta_v2.json` dailyBoss.layouts, `Layouts/*.json`).","",
"## What the game actually references","",
"* `LevelBuilder.Build` (Scripts/Level/LevelBuilder.cs) spawns **every layout block as a Unity cube** scaled to `s`, with `MaterialDefinition` from `mat` (wood / brick / steel). There is no per-level prefab or model lookup.",
"* `ArenaBuilder` builds only the island, pad, palms, clouds and cliff dressing (procedural). The island is **held**, so it is out of scope.",
"* `DailyBossRules.ForDate` picks one of `meta_v2.dailyBoss.layouts` (4 titan arenas), with materials wood/brick/steel. `titan_templates.json` arenas use the same 4 layouts.",
"* `GameSession.EnsureHeroSlot` loads `Resources/HeroBuildings/<heroSlot.fbx>`. Chapter 1 levels have **no heroSlot**, and OfflineMeta preview slots have `fbx=\"\"`. So **no Bld_* hero building (Townhouse, Keep, Tower, Gate) is used by L1-10 or the Daily Boss**. The realism-test Townhouse stays as the reference asset only.",
"* `/workspace/crashverse/design` has only rulings/specs (no extra level files), and there is no `levels/` folder. Level data lives only in the layouts above.","",
"So the realistic scope is the **material block pieces** the 14 layouts use, plus 2 dressed props (barrel decor, explosive crate). Each one maps to an existing BuildingKit module and is re-surfaced with the graded CC0 sets, using the kit v3.1 geometry and fracture.","",
"## Assets, most-used first (build order)","","| # | Realistic asset | Kind | Blocks | Levels (count) | Existing model it maps to |","|---|---|---|---|---|---|"]
for i,k in enumerate(order,1):
    u=use[k]; lv=", ".join(f"{t}x{n}" if n>1 else t for t,n in u["levels"].items())
    L.append(f"| {i} | `{k}` | {u['kind']} | {u['count']}{' ('+str(u['indestructible'])+' indestructible)' if u['indestructible'] else ''} | {lv} | {u['src']} |")
h=use.get("HELD")
if h: L+=["",f"Held (island): {h['count']} indestructible `role=island` rock/plinth/pier blocks ({', '.join(sorted(h['levels']))}). They map to Kit_Base_Indestructible / ArenaBuilder rock, and are not converted."]
L+=["","## Per level","","| Level | Layout | Block id | mat | role | size (m) | -> asset |","|---|---|---|---|---|---|---|"]
for tag,lay,b,mod,kind,src in rows:
    L.append(f"| {tag} | {lay} | {b['id']} | {b['mat']} | {b['role'] or '-'} | {' x '.join(f'{v:g}' for v in b['s'])} | {mod if mod!='HELD' else 'held (island)'} |")
L+=["","## Mapping a block to a piece (for Developer)","",
"* Each piece is authored at its kit size (Wall 3x3xt, Floor 3x3xt, Joint 0.3-0.4 x 3, Block 1x1x1, Roof 3.6x2.3). Scale it per block: `scale = block.s / piece.size` on the matching axes. Joint: the long axis goes to the block's longest axis. Wall: the thin axis goes to the block's thin axis.",
"* UV0 on every realistic piece is a **metric box projection** (`uv = position_m / tile_m` on the face's dominant axis). The textures are tiling sets, so after non-uniform scaling the UVs can be rebuilt from the scaled vertex positions with the same rule, and texel density stays constant. The tile size per kit is in `Kit_Real<M>_stats.json` (`tile_m`).",
"* Small dressing blocks (bell, flag, sails, lanterns, clock, sign, lamp, tank, wheel) are not separate models in the data. They use the material piece of their shape class (table above)."]
open(out,"w").write("\n".join(L)+"\n")
json.dump({"ref":REF,"order":order,"assets":{k:{**{x:y for x,y in use[k].items() if x!="levels"},"levels":dict(use[k]["levels"])} for k in use}},open(out[:-3]+".json","w"),indent=1)
print("\n".join(f"{i+1:2d} {k:26s} {use[k]['count']:3d} {dict(use[k]['levels'])}" for i,k in enumerate(order))); print("HELD",use.get("HELD",{}).get("count"))
